package org.skhuconnect.admin.notificationlog.service;
import org.skhuconnect.admin.entity.Admin; import org.skhuconnect.admin.notificationlog.dto.*; import org.skhuconnect.admin.notificationlog.entity.*; import org.skhuconnect.admin.notificationlog.repository.NotificationLogRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminNotificationLogService { private static final int MAX_PAGE_SIZE=100; private final NotificationLogRepository repository; public AdminNotificationLogService(NotificationLogRepository repository){this.repository=repository;}
 @Transactional public void record(NotificationLogType type,Admin admin,NotificationLogTargetType targetType,Long targetId,String description){repository.save(NotificationLog.create(type,admin,targetType,targetId,description));}
 @Transactional(readOnly=true) public AdminNotificationLogPageResponse findAll(int page,int size){if(page<0||size<1||size>MAX_PAGE_SIZE)throw new IllegalArgumentException("invalid page request"); Page<AdminNotificationLogResponse> result=repository.findAll(PageRequest.of(page,size,Sort.by(Sort.Order.desc("createdAt"),Sort.Order.desc("id")))).map(AdminNotificationLogResponse::from); return AdminNotificationLogPageResponse.from(result);}}